{"implementation": "def solve(case):
    # Validate required fields
    for field in ("nodes", "core_distance", "distances"):
        if field not in case:
            raise ValueError(f"Missing required field: {field}")

    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    if not isinstance(nodes, list) or len(nodes) == 0:
        raise ValueError("nodes must be a non-empty list")

    for node in nodes:
        if node not in core_distance:
            raise ValueError(f"Missing core_distance for node {node}")

    n = len(nodes)

    # Build distance lookup with canonicalized keys
    dist_map = {}
    for entry in distances:
        if len(entry) != 3:
            raise ValueError(f"Distance entry must have 3 elements: {entry}")
        u, v, d = entry[0], entry[1], entry[2]
        key = (min(u, v), max(u, v))
        dist_map[key] = d

    # Compute all mutual reachability edges
    node_list = list(nodes)
    mr_edges = []
    for i in range(n):
        for j in range(i + 1, n):
            u = node_list[i]
            v = node_list[j]
            key = (min(u, v), max(u, v))
            if key not in dist_map:
                raise ValueError(f"Missing distance for pair ({u}, {v})")
            d = dist_map[key]
            mr = max(core_distance[u], core_distance[v], d)
            eu, ev = min(u, v), max(u, v)
            mr_edges.append((mr, eu, ev))

    # Sort deterministically: primary by weight, secondary by canonicalized endpoints
    mr_edges.sort(key=lambda e: (e[0], e[1], e[2]))

    # Union-Find with path compression and union by rank
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    # Kruskal's MST
    selected = []
    total_weight = 0.0

    for mr, u, v in mr_edges:
        if union(u, v):
            selected.append({"u": u, "v": v, "weight": mr})
            total_weight += mr
            if len(selected) == n - 1:
                break

    if len(selected) != n - 1:
        raise ValueError("Input graph is disconnected; MST cannot be constructed")

    return {
        "mst_edges": selected,
        "total_weight": total_weight
    }
"}
